"use client";

import type { ReactNode } from "react";
import type { SplitNumberPreset } from "./split-number-field-state";

// Icons on a 16-unit grid: a faint box with the edited edge or corner drawn strong.
const icon = (children: ReactNode) => (
  <svg viewBox="0 0 16 16" aria-hidden className="size-4 shrink-0" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round">
    {children}
  </svg>
);
const box = <rect x={2.75} y={2.75} width={10.5} height={10.5} rx={2} strokeOpacity={0.35} />;
const edges = { top: "M4 2.75h8", right: "M13.25 4v8", bottom: "M4 13.25h8", left: "M2.75 4v8" };
const side = (edge: keyof typeof edges) => icon([<g key="box">{box}</g>, <path key="edge" d={edges[edge]} />]);
// A corner arc, turned into place.
const corner = (turn: number) => icon([<g key="box">{box}</g>, <path key="arc" d="M2.75 8V5.75a3 3 0 0 1 3-3H8" transform={`rotate(${turn} 8 8)`} />]);

const icons = {
  horizontal: icon([<g key="box">{box}</g>, <path key="lines" d="M5.5 5.5v5M10.5 5.5v5" />]),
  vertical: icon([<g key="box">{box}</g>, <path key="lines" d="M5.5 5.5h5M5.5 10.5h5" />]),
  all: icon(<rect x={2.75} y={2.75} width={10.5} height={10.5} rx={3} />),
  allSides: icon(<rect x={2.75} y={2.75} width={10.5} height={10.5} rx={2} />),
  // Four corner brackets: open the value into its parts.
  split: icon(<path d="M2.75 6V4.75a2 2 0 0 1 2-2H6M10 2.75h1.25a2 2 0 0 1 2 2V6M13.25 10v1.25a2 2 0 0 1-2 2H10M6 13.25H4.75a2 2 0 0 1-2-2V10" />),
};

// Split sides keep the merged columns: left and right under horizontal, top and bottom under vertical.
const sides = [
  { key: "left", label: "left", icon: side("left") },
  { key: "top", label: "top", icon: side("top") },
  { key: "right", label: "right", icon: side("right") },
  { key: "bottom", label: "bottom", icon: side("bottom") },
];

/** Padding or margin: horizontal and vertical, then left and right beneath horizontal, top and bottom beneath vertical. */
export const sidesPreset: SplitNumberPreset = {
  toggleLabel: "Individual sides",
  toggleIcon: icons.split,
  levels: [
    [
      { key: "horizontal", label: "horizontal", icon: icons.horizontal, covers: ["left", "right"] },
      { key: "vertical", label: "vertical", icon: icons.vertical, covers: ["top", "bottom"] },
    ],
    sides,
  ],
};

/** Border width, or any value usually the same on every side: one value, then each side, left first. */
export const allSidesPreset: SplitNumberPreset = {
  toggleLabel: "Individual sides",
  toggleIcon: icons.split,
  levels: [[{ key: "all", label: "all sides", icon: icons.allSides, covers: ["left", "top", "right", "bottom"] }], sides],
};

/** Corner radius: one value, then each corner where it sits. */
export const cornersPreset: SplitNumberPreset = {
  toggleLabel: "Individual corners",
  toggleIcon: icons.split,
  levels: [
    [{ key: "all", label: "all corners", icon: icons.all, covers: ["topLeft", "topRight", "bottomLeft", "bottomRight"] }],
    [
      { key: "topLeft", label: "top left", icon: corner(0) },
      { key: "topRight", label: "top right", icon: corner(90) },
      { key: "bottomLeft", label: "bottom left", icon: corner(270) },
      { key: "bottomRight", label: "bottom right", icon: corner(180) },
    ],
  ],
};

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef, useState } from "react";
import { NumberField, NumberFieldError, NumberFieldGroup, NumberFieldInput, NumberFieldScrubArea, NumberFieldUnit } from "@/components/ui/number-field";
import {
  type SplitNumberFieldContextValue,
  type SplitNumberFieldProps,
  type SplitNumberPart,
  type SplitNumberValue,
  SplitNumberFieldContext,
  defaultMessages,
  distinctValues,
  fittingLevel,
  keysOf,
  sharedValue,
  useSplitNumberField,
} from "./split-number-field-state";
import { cn } from "@/lib/utils";

/**
 * A number that splits into linked parts, such as padding into its sides or radius into its corners.
 * A merged part whose sides differ lists their values, such as "8, 20"; typing or dragging it sets everything it covers.
 * The layout is a two-column grid with the toggle at the end of the first row.
 */
export const SplitNumberField = forwardRef<HTMLDivElement, SplitNumberFieldProps>(function SplitNumberField(
  {
    label,
    preset,
    value,
    onValueCommit,
    onValueChange,
    level: levelProp,
    defaultLevel,
    onLevelChange,
    align = "start",
    messages: messagesProp,
    unit,
    min,
    max,
    step,
    largeStep,
    precision,
    format,
    parse,
    validate,
    sensitivity,
    disabled = false,
    readOnly,
    motion,
    className,
    ...props
  },
  ref,
) {
  const messages = { ...defaultMessages, ...messagesProp };
  // Starts at the first level that shows the value without hiding a difference.
  const [levelState, setLevelState] = useState(() => defaultLevel ?? fittingLevel(preset, value));
  const level = Math.min(levelProp ?? levelState, preset.levels.length - 1);
  const apply = (part: SplitNumberPart, next: number): [SplitNumberValue, { changed: string[] }] => {
    const changed = keysOf(part);
    return [{ ...value, ...Object.fromEntries(changed.map((key) => [key, next])) }, { changed }];
  };
  const show = (item: number) => (format ? format(item) : String(item));

  /**
   * Reads a typed list onto the sides a part covers. As many values as it shows replace those values
   * wherever they appear ("12, 0" over 12, 12, 0, 0); as many as it covers go in order. One value
   * is left to the field.
   */
  const submitList = (part: SplitNumberPart, text: string): true | string | undefined => {
    const tokens = text.split(/[\s,]+/).filter(Boolean);
    if (tokens.length < 2) return undefined;
    const numbers = tokens.map((token) => Number((unit && token.endsWith(unit) ? token.slice(0, -unit.length) : token).replace(/−/g, "-")));
    if (numbers.some((item) => !Number.isFinite(item))) return undefined;
    if (numbers.some((item) => (min !== undefined && item < min) || (max !== undefined && item > max))) return messages.listRange(min, max);
    const keys = keysOf(part);
    const shown = distinctValues(value, keys);
    let next: Record<string, number>;
    if (shown && shown.length > 1 && numbers.length === shown.length) {
      next = Object.fromEntries(keys.map((key) => [key, numbers[shown.indexOf(value[key] as number)]]));
    } else if (numbers.length === keys.length) {
      next = Object.fromEntries(keys.map((key, index) => [key, numbers[index]]));
    } else {
      const counts = [...new Set([1, ...(shown && shown.length > 1 ? [shown.length] : []), keys.length])].sort((a, b) => a - b);
      return messages.listCount(counts);
    }
    const changed = keys.filter((key) => value[key] !== next[key]);
    if (changed.length) onValueCommit({ ...value, ...next }, { changed });
    return true;
  };

  const context: SplitNumberFieldContextValue = {
    label,
    preset,
    level,
    setLevel: (next) => {
      if (levelProp === undefined) setLevelState(next);
      onLevelChange?.(next);
    },
    parts: preset.levels[level],
    read: (part) => sharedValue(value, keysOf(part)),
    placeholder: (part) => {
      const values = distinctValues(value, keysOf(part));
      return values ? messages.values(values.map(show)) : messages.mixed;
    },
    editText: (part) => {
      const values = distinctValues(value, keysOf(part));
      return values && values.length > 1 ? messages.values(values.map(show)) : undefined;
    },
    submitList,
    preview: (part, next) => onValueChange?.(...apply(part, next)),
    commit: (part, next) => onValueCommit(...apply(part, next)),
    field: { unit, min, max, step, largeStep, precision, format, parse, validate, sensitivity, disabled, readOnly, motion },
    align,
    disabled,
    messages,
  };

  return (
    <SplitNumberFieldContext.Provider value={context}>
      <div
        ref={ref}
        role="group"
        aria-label={label}
        data-level={level}
        data-split={level === preset.levels.length - 1 || undefined}
        data-align={align}
        className={cn("grid min-w-0 grid-cols-[minmax(0,1fr)_minmax(0,1fr)_auto] items-start gap-2", className)}
        {...props}
      />
    </SplitNumberFieldContext.Provider>
  );
});

type PartsProps = {
  /** Class for each part's box, input, icon and error. */
  groupClassName?: string;
  inputClassName?: string;
  iconClassName?: string;
  errorClassName?: string;
  /** Replace a part's contents inside its Number Field; receives the part. */
  children?: (part: SplitNumberPart) => ReactNode;
};

/**
 * The current level's parts, each a Number Field labelled by its icon: drag the icon or the number,
 * type, or step with the arrow keys. They fill two columns, so four parts form a 2×2 grid.
 */
export function SplitNumberFieldParts({ groupClassName, inputClassName, iconClassName, errorClassName, children }: PartsProps) {
  const split = useSplitNumberField();
  const single = split.parts.length === 1;
  return split.parts.map((part, index) => (
    <NumberField
      key={part.key}
      {...split.field}
      label={split.messages.part(split.label, part.label)}
      placeholder={split.placeholder(part)}
      editText={split.editText(part)}
      submitText={(text) => split.submitList(part, text)}
      value={split.read(part)}
      onValueChange={(next) => split.preview(part, next)}
      onValueCommit={(next) => split.commit(part, next)}
      data-part={part.key}
      // Parts keep to the first two columns; the toggle owns the third column of the first row.
      className={cn("min-w-0 flex-nowrap", single ? "col-span-2 col-start-1" : index % 2 === 0 ? "col-start-1" : "col-start-2", "flex-col items-stretch gap-1")}
    >
      {children ? (
        children(part)
      ) : (
        <>
          {/* The part stacks its box over its error, so the box must not shrink to its content. */}
          <NumberFieldGroup className={cn("flex-none", groupClassName)}>
            <NumberFieldScrubArea className={cn("pl-2 text-muted-foreground", iconClassName)}>{part.icon}</NumberFieldScrubArea>
            <NumberFieldInput className={cn(split.align === "start" && "pl-1.5 text-left", inputClassName)} />
            <NumberFieldUnit />
          </NumberFieldGroup>
          <NumberFieldError className={errorClassName} />
        </>
      )}
    </NumberField>
  ));
}

/** Moves to the next level, wrapping back to the first. Pressed while fully split. */
export const SplitNumberFieldToggle = forwardRef<HTMLButtonElement, Omit<ComponentPropsWithoutRef<"button">, "children">>(function SplitNumberFieldToggle(
  { className, onClick, ...props },
  ref,
) {
  const split = useSplitNumberField();
  const last = split.preset.levels.length - 1;
  return (
    <button
      ref={ref}
      type="button"
      aria-label={split.preset.toggleLabel}
      aria-pressed={split.level === last}
      disabled={split.disabled}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) split.setLevel(split.level === last ? 0 : split.level + 1);
      }}
      className={cn(
        "col-start-3 row-start-1 grid h-[var(--uicoolkit-field-height,2.5rem)] w-10 border border-[color:var(--uicoolkit-field-icon-border,transparent)] bg-[var(--uicoolkit-field-icon-bg,transparent)] place-items-center rounded-md text-muted-foreground outline-none transition-colors",
        "hover:bg-muted hover:text-foreground focus-visible:bg-foreground/10 focus-visible:text-foreground disabled:pointer-events-none disabled:opacity-50",
        "aria-pressed:bg-primary/10 aria-pressed:text-foreground",
        className,
      )}
      {...props}
    >
      {split.preset.toggleIcon}
    </button>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, createContext, useContext } from "react";
import type { NumberFieldProps } from "@/components/ui/number-field";

/** One editable value: a side, a corner, or a merged group of them. */
export type SplitNumberPart = {
  key: string;
  /** Read after the field's label, such as "top" in "Padding top". */
  label: string;
  icon?: ReactNode;
  /** The finest parts this one sets. Omit on the finest level, where a part covers itself. */
  covers?: string[];
};

/**
 * How a value splits. Each level is a set of parts, from merged to fully split; the last level's
 * keys are what your app stores. The toggle moves to the next level and wraps back to the first.
 */
export type SplitNumberPreset = {
  levels: SplitNumberPart[][];
  /** Names the toggle, such as "Individual sides". */
  toggleLabel: string;
  toggleIcon?: ReactNode;
};

/** Every finest part's value; null where a selection holds different values. */
export type SplitNumberValue = Record<string, number | null>;

/** What a change touched: the finest parts that received the new value. */
export type SplitNumberChange = { changed: string[] };

export type SplitNumberFieldMessages = {
  /** Shown when a part covers a value that differs across a selection, so its values are unknown. */
  mixed: string;
  /** Shown in a merged part whose sides differ: each different value once, in order, such as "8, 20". */
  values: (values: string[]) => string;
  part: (label: string, part: string) => string;
  /** Rejects a typed list whose length fits neither the shown values nor the sides it covers. */
  listCount: (counts: number[]) => string;
  /** Rejects a typed list with a value outside the limits. */
  listRange: (min: number | undefined, max: number | undefined) => string;
};

export const defaultMessages: SplitNumberFieldMessages = {
  mixed: "Mixed",
  values: (values) => values.join(", "),
  part: (label, part) => `${label} ${part}`,
  listCount: (counts) => `Enter ${counts.length === 1 ? counts[0] : `${counts.slice(0, -1).join(", ")} or ${counts[counts.length - 1]}`} values.`,
  listRange: (min, max) => (min !== undefined && max !== undefined ? `Enter values from ${min} to ${max}.` : min !== undefined ? `Enter values of ${min} or more.` : `Enter values of ${max} or less.`),
};

type Passed = Pick<NumberFieldProps, "unit" | "min" | "max" | "step" | "largeStep" | "precision" | "format" | "parse" | "validate" | "sensitivity" | "disabled" | "readOnly" | "motion">;

export type SplitNumberFieldProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue"> &
  Passed & {
    /** Names the whole value, such as "Padding". Each part reads as the label and its part. */
    label: string;
    preset: SplitNumberPreset;
    /** Every finest part's value. Your app owns it. */
    value: SplitNumberValue;
    /** Called once per finished edit with every part and the parts it changed, so a selection can apply only those. */
    onValueCommit: (value: SplitNumberValue, change: SplitNumberChange) => void;
    /** Live values while dragging a part, for previewing on your canvas. */
    onValueChange?: (value: SplitNumberValue, change: SplitNumberChange) => void;
    /** Which level shows, as an index into the preset's levels. Leave it out to let the field choose. */
    level?: number;
    /** The level to start at. Defaults to the first one that can show the value without hiding a difference. */
    defaultLevel?: number;
    onLevelChange?: (level: number) => void;
    /** Where values sit in each part: after the icon, or at the end beside the unit. Matches Inspector Field's align. */
    align?: "start" | "end";
    messages?: Partial<SplitNumberFieldMessages>;
  };

export type SplitNumberFieldContextValue = {
  label: string;
  preset: SplitNumberPreset;
  level: number;
  setLevel: (level: number) => void;
  parts: SplitNumberPart[];
  /** The value a part shows: shared by everything it covers, or null when they differ. */
  read: (part: SplitNumberPart) => number | null;
  /** What a part shows in place of a value: its different values, or Mixed for a selection. */
  placeholder: (part: SplitNumberPart) => string;
  /** The list a merged part's typing starts from, when its sides differ. */
  editText: (part: SplitNumberPart) => string | undefined;
  /** Applies typed text that is a list, such as "8, 20"; see SplitNumberFieldParts. */
  submitList: (part: SplitNumberPart, text: string) => true | string | undefined;
  preview: (part: SplitNumberPart, value: number) => void;
  commit: (part: SplitNumberPart, value: number) => void;
  field: Passed;
  align: "start" | "end";
  disabled: boolean;
  messages: SplitNumberFieldMessages;
};

export const SplitNumberFieldContext = createContext<SplitNumberFieldContextValue | null>(null);

/** State of the nearest SplitNumberField, for custom parts. */
export function useSplitNumberField() {
  const context = useContext(SplitNumberFieldContext);
  if (!context) throw new Error("Split Number Field parts must be used inside <SplitNumberField>.");
  return context;
}

/** The finest keys a part sets. */
export const keysOf = (part: SplitNumberPart) => part.covers ?? [part.key];

/** The shared value of some keys, or null when they differ or any is mixed. */
export function sharedValue(value: SplitNumberValue, keys: string[]) {
  const first = value[keys[0]] ?? null;
  return keys.every((key) => (value[key] ?? null) === first) ? first : null;
}

/** The different values a part covers, each once and in order; null when any is unknown across a selection. */
export function distinctValues(value: SplitNumberValue, keys: string[]) {
  const values = keys.map((key) => value[key] ?? null);
  if (values.some((item) => item === null)) return null;
  return [...new Set(values as number[])];
}

/** The first level whose parts each cover equal values, so merging hides no difference. */
export function fittingLevel(preset: SplitNumberPreset, value: SplitNumberValue) {
  const index = preset.levels.findIndex((parts) => parts.every((part) => keysOf(part).every((key) => (value[key] ?? null) === (value[keysOf(part)[0]] ?? null))));
  return index < 0 ? preset.levels.length - 1 : index;
}

"use client";

export {
  type SplitNumberFieldProps,
  type SplitNumberFieldMessages,
  type SplitNumberPart,
  type SplitNumberPreset,
  type SplitNumberValue,
  type SplitNumberChange,
  useSplitNumberField,
} from "./split-number-field-state";
export { SplitNumberField, SplitNumberFieldParts, SplitNumberFieldToggle } from "./split-number-field-root";
export { sidesPreset, allSidesPreset, cornersPreset } from "./split-number-field-presets";
